I tried today my old nodejs code and everything works. Does it mean cluster was implemented recently? Code here:

```js
import cluster from 'cluster';
import express from 'express';
import promBundle from 'express-prom-bundle';

const MAX_CPU = 4;

if (cluster.isPrimary) {
    console.log(`Master ${process.pid} is running`);

    for (let i = 0; i < MAX_CPU; i++) {
        cluster.fork();
    }
    const metricsApp = express();
    metricsApp.use('/metrics', promBundle.clusterMetrics());
    metricsApp.listen(6022);
    cluster.on('exit', (worker) => {
        console.log(`Worker ${worker.process.pid} died`);
        cluster.fork();
    });
} else {
    import('./app.js');
}
```
